css.value:
* {
	font-feature-settings: 'clig' off, 'liga' off;
	font-family: Lato;
	font-size: 1rem;
	font-style: normal;
	font-weight: 400;
	line-height: normal;
}

script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let selectedUsers = [];
	for (let x = 0; x < event.payload.value.length; x++)
            selectedUsers.push(event.payload.value[x].sysId);
	return {
		propName: 'selectedUsers',
		value: selectedUsers
	};
}
